output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "Agents may not move from an open aisle into a single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "cart_drop_only_at_aisle_mouth",
    "text": "Carts may only be put down at designated mouths of single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "singleFileMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart at the mouth of a single-file aisle, the agent must retrieve the cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "parked_cart_means_enter_narrow_aisle",
    "text": "Once an agent has put down a cart at a single-file aisle mouth, walking away without the cart is only allowed if the next cell is inside the single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartlessMoveFromMouthToNonSingleFile": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "not": "singleFileAisle"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessMoveFromMouthToNonSingleFile"
    }
  },
  {
    "id": "retrieve_cart_on_return_from_single_file",
    "text": "When an agent returns on foot from a single-file shelf aisle to its mouth, they must pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "returnToMouthOnFoot": {
          "pre": {
            "and": [
              "singleFileAisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileMouth"
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnToMouthOnFoot",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "side_shelf_service_on_foot",
    "text": "Items on side-facing shelves in single-file aisles must be collected without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileSideShelf": {
          "and": [
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileSideShelf",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "open_aisle_shelf_requires_cart",
    "text": "Shelf interactions in broad open aisles should be performed with a cart.",
    "abstraction": {
      "state_properties": {
        "openAisleShelf": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "or": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openAisleShelf",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
